async function ensureSoilRenderer(){if(window.ITA_SOIL_RENDERER_META?.loaded&&Object.keys(window.ITA_SOIL_RENDERER_COLORS||{}).length)return window.ITA_SOIL_RENDERER_COLORS;const cacheKey='ita_arandu_soil_renderer_pinms_42_v1';try{const cached=localStorage.getItem(cacheKey);if(cached){const o=JSON.parse(cached);if(o&&o.colors&&Object.keys(o.colors).length){window.ITA_SOIL_RENDERER_COLORS=o.colors;window.ITA_SOIL_RENDERER_META={loaded:true,cached:true,classes:Object.keys(o.colors).length,source:'PIN MS · Solos-MS 1:250.000 · layer 42'};return o.colors}}}catch(e){}const r=await fetch(ITA_SOIL_RENDERER_URL,{cache:'no-store'});if(!r.ok)throw new Error(`Renderer de solos PIN MS indisponível (${r.status})`);const j=await r.json();const infos=j?.drawingInfo?.renderer?.uniqueValueInfos||[];const colors={};for(const it of infos){const v=String(it.value??it.label??'');const c=rgbaArrayToCss(it.symbol?.color);if(v&&c)colors[v]=c}if(!Object.keys(colors).length)throw new Error('Renderer de solos sem classes legíveis');window.ITA_SOIL_RENDERER_COLORS=colors;window.ITA_SOIL_RENDERER_META={loaded:true,cached:false,classes:Object.keys(colors).length,source:'PIN MS · Solos-MS 1:250.000 · layer 42',capturado_em:new Date().toISOString()};try{localStorage.setItem(cacheKey,JSON.stringify({colors,saved_at:new Date().toISOString()}))}catch(e){}return colors}
