function surfaceCoverMatch(p){const t=surfaceCoverText(p);return /cobertura|deposito aluv|depositos aluv|deposito coluv|depositos coluv|terraco aluv|pantanal|xaraies/.test(t)}
function surfaceCoverClass(p){const t=surfaceCoverText(p);if(/detrito.?laterit|laterit/.test(t))return'Coberturas detrito-lateríticas';if(/terraco aluv/.test(t))return'Terraços aluvionares';if(/coluv/.test(t))return'Depósitos coluvionares';if(/aluv/.test(t))return'Depósitos aluvionares';if(/pantanal/.test(t))return'Depósitos do Pantanal';if(/xaraies/.test(t))return'Xaraiés';return'Outras coberturas superficiais'}
