function itaNorm(v){return String(v||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase()}
function carbonaticText(p){return itaNorm([p?.NOME,p?.NOME_PAI,p?.LITOTIPOS,p?.LEGENDA].filter(Boolean).join(' '))}
function isCarbonaticUnit(p){const t=carbonaticText(p);return ['calcario','dolomito','marmore','carbonat','calcarenito','calcilutito'].some(k=>t.includes(k))}
