function itaPointInRing(pt,ring){let inside=false;const x=pt[0],y=pt[1];for(let i=0,j=ring.length-1;i<ring.length;j=i++){const xi=ring[i][0],yi=ring[i][1],xj=ring[j][0],yj=ring[j][1];const hit=((yi>y)!=(yj>y))&&(x<(xj-xi)*(y-yi)/((yj-yi)||1e-15)+xi);if(hit)inside=!inside}return inside}
function itaPointInPolygonCoords(pt,poly){if(!poly?.length||!itaPointInRing(pt,poly[0]))return false;for(let i=1;i<poly.length;i++)if(itaPointInRing(pt,poly[i]))return false;return true}
function itaPointInGeom(pt,g){if(!g)return false;if(g.type==='Polygon')return itaPointInPolygonCoords(pt,g.coordinates);if(g.type==='MultiPolygon')return g.coordinates.some(p=>itaPointInPolygonCoords(pt,p));return false}
function itaGeomBBox(g){let xmin=Infinity,ymin=Infinity,xmax=-Infinity,ymax=-Infinity;const scan=o=>{if(!Array.isArray(o))return;if(typeof o[0]==='number'&&typeof o[1]==='number'){xmin=Math.min(xmin,o[0]);xmax=Math.max(xmax,o[0]);ymin=Math.min(ymin,o[1]);ymax=Math.max(ymax,o[1]);return}o.forEach(scan)};scan(g?.coordinates);return[xmin,ymin,xmax,ymax]}
function itaScaleScore(scale){const m=Number(scale);return Number.isFinite(m)&&m>0?Math.min(1,100000/m):null}
