async function buildImcSnapshotV32(cfg){
 const gridCfg=CATALOG.layers.find(x=>x.id===cfg.grid_source_id);
 if(!gridCfg)throw new Error('Malha do IMC V32 não encontrada no catálogo');
 const grid=await ensure(gridCfg),key=String(cfg.imc_scale||''),scores=window.ITA_IMC_V32?.grids?.[key];
 if(!scores)throw new Error('Snapshot IMC V32 não encontrado para esta escala');
 const features=(grid.features||[]).map(hf=>{
  const hid=String(hf.properties?.hex_id||''),r=scores[hid];
  if(!r)return {...hf,properties:{...(hf.properties||{}),imc_100:null,classe_imc:'sem dados',metodo:'V32 · snapshot local · célula sem registro materializado'}};
  const [imc,p100,p250,p1000,best,sheets,area]=r;
  return {...hf,properties:{...(hf.properties||{}),imc_100:imc,classe_imc:imcClass(imc),pct_100k:p100,pct_250k:p250,pct_1000k:p1000,melhor_escala_detectada:best,folhas_detalhadas_intersectadas:(sheets||[]).join(' · ')||'nenhuma folha detalhada materializada nesta célula',area_calculo_km2:area,formula:'IMC_h = 100 × [1,00 A100 + 0,40 A250 + 0,10 A1000] / A_h',metodo:'V32 · interseção areal exata em Lambert Azimutal Equal-Area · melhor escala prevalece nas sobreposições',base_minima:'SGB/CPRM · Mato Grosso do Sul 1:1.000.000 · 2006',cobertura_detalhada:'snapshot conservador de folhas SGB/CPRM com código cartográfico e escala verificados',limite_metodologico:'Projetos conhecidos sem polígono exato materializado neste corte não são imputados espacialmente. Constam como pendentes de captura.',data_calculo:'2026-08-13'}};
 });
 return {type:'FeatureCollection',features,atlas_metadata:{indice:'IMC',versao:'V32',escala_grade:cfg.name,formula:'IMC_h = 100 × [1,00 A100 + 0,40 A250 + 0,10 A1000] / A_h',base:'SGB/CPRM 1:1.000.000 · 2006',cobertura:'13 folhas detalhadas verificadas neste snapshot',metodo:'interseção areal exata em projeção equivalente',regra:'a escala mais detalhada prevalece em sobreposições',limite:'projetos sem polígono exato materializado permanecem pendentes'}};
}
