function itaArmDocumentHistory(){if(ITA_DOC_HISTORY_ARMED)return;try{ITA_DOC_HISTORY_TOKEN=`ita-doc-${Date.now()}-${Math.random().toString(36).slice(2)}`;history.pushState(Object.assign({},history.state||{},{itaDocumentViewer:ITA_DOC_HISTORY_TOKEN}),'',location.href);ITA_DOC_HISTORY_ARMED=true}catch(_){ITA_DOC_HISTORY_TOKEN=null;ITA_DOC_HISTORY_ARMED=false}}
function itaOpenInternalDocument(url,title){const frame=document.getElementById('documentoFrame');if(!frame)return;ITA_DOC_STACK=[];openModal('documentoModal');itaArmDocumentHistory();itaDocReplace(url,title||'Documentação')}
function itaDocNavigate(url,title){const frame=document.getElementById('documentoFrame');if(!frame)return;const current=frame.dataset.currentUrl;if(current)ITA_DOC_STACK.push({url:current,title:frame.dataset.currentTitle||document.getElementById('documentoTitle')?.textContent||'Documentação'});itaDocReplace(url,title||'Documentação')}
function itaCloseDocumentViewer(fromHistory=false){const frame=document.getElementById('documentoFrame');ITA_DOC_STACK=[];if(fromHistory){ITA_DOC_HISTORY_ARMED=false;ITA_DOC_HISTORY_TOKEN=null;closeModal('documentoModal');try{frame?.contentWindow?.location?.replace('about:blank')}catch(_){};return}if(ITA_DOC_HISTORY_ARMED&&history.state?.itaDocumentViewer===ITA_DOC_HISTORY_TOKEN){try{history.back();return}catch(_){}}ITA_DOC_HISTORY_ARMED=false;ITA_DOC_HISTORY_TOKEN=null;closeModal('documentoModal');try{frame?.contentWindow?.location?.replace('about:blank')}catch(_){}}
function itaDocumentBack(){if(ITA_DOC_STACK.length){const prev=ITA_DOC_STACK.pop();itaDocReplace(prev.url,prev.title);return}itaCloseDocumentViewer()}
function itaConfigureDocumentFrame(){const frame=document.getElementById('documentoFrame');if(!frame)return;try{const doc=frame.contentDocument,win=frame.contentWindow;if(!doc||!win||win.location.href==='about:blank')return;frame.dataset.currentUrl=win.location.href;const title=doc.querySelector('h1')?.textContent?.trim()||doc.title||frame.dataset.currentTitle||'Documentação';frame.dataset.currentTitle=title;const ttl=document.getElementById('documentoTitle');if(ttl)ttl.textContent=title;doc.querySelectorAll('a[href]').forEach(link=>{let u;try{u=new URL(link.getAttribute('href'),win.location.href)}catch(_){return}if(u.origin!==location.origin){link.target='_blank';link.rel='noopener noreferrer';return}link.removeAttribute('target');link.removeAttribute('rel')});doc.addEventListener('click',e=>{const link=e.target.closest?.('a[href]');if(!link)return;let u;try{u=new URL(link.getAttribute('href'),win.location.href)}catch(_){return}if(u.origin!==location.origin)return;const scopeRoot=new URL('./',location.href);const isAtlasRoot=u.pathname===scopeRoot.pathname||u.pathname===new URL('./index.html',location.href).pathname;if(isAtlasRoot){e.preventDefault();itaCloseDocumentViewer();return}if(!itaIsInternalDocUrl(u.href,win.location.href))return;e.preventDefault();const current=new URL(win.location.href);if(u.pathname===current.pathname&&u.search===current.search&&u.hash){const id=decodeURIComponent(u.hash.slice(1));const target=doc.getElementById(id)||doc.querySelector(`[name="${CSS.escape(id)}"]`);target?.scrollIntoView({block:'start'});return}const linkTitle=link.textContent?.trim()||'Documentação';itaDocNavigate(u.href,linkTitle)},{capture:true})}catch(_){} }
document.getElementById('documentoFrame')?.addEventListener('load',itaConfigureDocumentFrame);
document.getElementById('documentoBack')?.addEventListener('click',itaDocumentBack);
