init();


function itaFmtMa(v){if(v===null||v===undefined||!Number.isFinite(Number(v)))return '—';const n=Number(v);if(n===0)return '0 Ma';if(n<.1)return `${(n*1000).toLocaleString('pt-BR',{maximumFractionDigits:1})} ka`;return `${n.toLocaleString('pt-BR',{maximumFractionDigits:3})} Ma`}
function itaAgeRange(oldAge,youngAge){return `${itaFmtMa(oldAge)} – ${itaFmtMa(youngAge)}`}
function itaEsc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function itaIntervalsOverlap(old1,young1,old2,young2){return Math.min(old1,old2)>=Math.max(young1,young2)}
function itaPeriodsForRange(oldAge,youngAge){return (window.ITA_ICS?.periods||[]).filter(p=>itaIntervalsOverlap(oldAge,youngAge,p.begin,p.end))}
function itaEraForAge(age){return (window.ITA_ICS?.eras||[]).find(e=>age<=e.begin&&age>=e.end)}
function itaPeriodOrEraColor(oldAge,youngAge){const ps=itaPeriodsForRange(oldAge,youngAge);if(ps.length)return ps[0].color;const e=itaEraForAge((oldAge+youngAge)/2);return e?.color||'#7390a3'}
function itaRenderICSColumn(){const host=document.getElementById('icsTimeColumn');if(!host)return;const I=window.ITA_ICS||{},eons=I.eons||[],eras=I.eras||[],periods=I.periods||[];host.innerHTML=eons.map(e=>{const es=eras.filter(x=>x.broader===e.id);let inner='';if(es.length){inner=es.map(er=>{const ps=periods.filter(p=>p.broader===er.id);return `<div class="era-block"><div class="era-title"><span class="era-dot" style="background:${er.color}"></span>${itaEsc(er.label)} <span class="age-range">${itaAgeRange(er.begin,er.end)}</span></div>${ps.map(p=>`<div class="period-row"><span class="period-color" style="background:${p.color}"></span><div><div class="period-name">${itaEsc(p.label)}</div><div class="period-en">${itaEsc(p.en)}</div></div><span class="age-range">${itaAgeRange(p.begin,p.end)}</span></div>`).join('')}</div>`}).join('')}else inner='<div class="era-block"><span class="period-en">Sem subdivisão por era exibida neste nível.</span></div>';return `<article class="eon-block"><div class="eon-title"><span class="eon-color" style="background:${e.color}"></span><div><b>${itaEsc(e.label)}</b><div class="period-en">${itaEsc(e.en)}</div></div><span class="age-range">${itaAgeRange(e.begin,e.end)}</span></div>${inner}</article>`}).join('')}
function itaMsTimeUnits(){const fc=window.ATLAS_DATA?.mapa_geologico_ms;if(!fc?.features)return[];const map=new Map();for(const f of fc.features){const p=f.properties||{},id=String(p.ID_UNIDADE_ESTRATIGRAFICA??p.SIGLA??p.NOME??'');if(!id||map.has(id))continue;const a=Number(p.IDADE_MIN),b=Number(p.IDADE_MAX);const young=Number.isFinite(a)&&Number.isFinite(b)?Math.min(a,b):null,old=Number.isFinite(a)&&Number.isFinite(b)?Math.max(a,b):null;map.set(id,{id,sigla:p.SIGLA||'',nome:p.NOME||'Unidade sem nome',hierarquia:p.HIERARQUIA||'',pai:p.NOME_PAI||'',range:p.RANGE||'',litotipos:p.LITOTIPOS||'',eraMin:p.ERA_MIN||'',eraMax:p.ERA_MAX||'',old,young})}return [...map.values()].sort((x,y)=>(y.old??-1)-(x.old??-1)||(y.young??-1)-(x.young??-1)||x.nome.localeCompare(y.nome,'pt-BR'))}
let ITA_MS_TIME_CACHE=[];
async function itaEnsureMsTimeSource(){
 if(window.ATLAS_DATA?.mapa_geologico_ms?.features?.length)return window.ATLAS_DATA.mapa_geologico_ms;
 const host=document.getElementById('msTimeColumn'),count=document.getElementById('tempoMsCount');
 if(host)host.innerHTML='<div class="empty">Carregando unidades geológicas de Mato Grosso do Sul…</div>';
 if(count)count.textContent='carregando';
 try{
  const data=await loadLocalLayer('mapa_geologico_ms');
  if(!data?.features?.length)throw new Error('a fonte local não contém feições');
  window.ATLAS_DATA=window.ATLAS_DATA||{};window.ATLAS_DATA.mapa_geologico_ms=data;
  ITA_MS_TIME_CACHE=[];
  return data
 }catch(err){
  console.warn('ITA ARANDU MS · coluna temporal de MS',err);
  if(host)host.innerHTML=`<div class="empty">Não foi possível carregar a coluna temporal de MS. ${itaEsc(err?.message||String(err))}. O mapa e as demais ferramentas continuam disponíveis.</div>`;
  if(count)count.textContent='fonte indisponível';
  return null
 }
}
async function itaRenderMsTime(filter=''){
 const host=document.getElementById('msTimeColumn'),count=document.getElementById('tempoMsCount');if(!host)return;
 if(!ITA_MS_TIME_CACHE.length){const data=await itaEnsureMsTimeSource();if(!data)return;ITA_MS_TIME_CACHE=itaMsTimeUnits()}
 const q=String(filter||'').trim().toLocaleLowerCase('pt-BR');const rows=ITA_MS_TIME_CACHE.filter(u=>!q||[u.sigla,u.nome,u.hierarquia,u.pai,u.range,u.litotipos,u.eraMin,u.eraMax,String(u.old),String(u.young)].join(' ').toLocaleLowerCase('pt-BR').includes(q));if(count)count.textContent=`${rows.length} de ${ITA_MS_TIME_CACHE.length} unidades`;host.innerHTML=rows.length?rows.map(u=>{const ps=(u.old!==null&&u.young!==null)?itaPeriodsForRange(u.old,u.young):[];const eq=ps.length?ps.map(p=>p.label).join(' · '):((u.old!==null&&u.young!==null)?(itaEraForAge((u.old+u.young)/2)?.label||'sem equivalência automática'):'idade não disponível');const color=(u.old!==null&&u.young!==null)?itaPeriodOrEraColor(u.old,u.young):'#7890a0';const search=itaEsc([u.sigla,u.nome,u.hierarquia,u.pai,u.range,u.litotipos,eq].join(' '));return `<article class="ms-unit" data-search="${search}"><span class="ms-unit-color" style="background:${color}"></span><div class="ms-unit-body"><div class="ms-unit-head"><div class="ms-unit-name"><span class="ms-unit-sigla">${itaEsc(u.sigla||u.range||'MS')}</span>${itaEsc(u.nome)}</div><div class="ms-unit-age">${u.old!==null?itaAgeRange(u.old,u.young):'idade —'}</div></div><div class="ms-unit-meta">${itaEsc(u.hierarquia||'hierarquia não informada')}${u.pai?` · unidade-pai ${itaEsc(u.pai)}`:''}${u.litotipos?`<br>${itaEsc(u.litotipos)}`:''}</div><div class="ms-unit-ics"><b>Equivalência temporal ICS 2026-06</b> · ${itaEsc(eq)}</div></div></article>`}).join(''):'<div class="empty">Nenhuma unidade corresponde ao filtro.</div>'
}
