const ITA_FIELD_DB='ita_arandu_campo_v01', ITA_FIELD_STORE='field_records', ITA_FIELD_DRAFT='ita_arandu_campo_draft_v03';
let campoDB=null, campoSelectedFiles=[], campoPhotoMeta=[], campoMeasures=[], campoSamples=[], campoCurrentStep=1, campoMode='completo', campoDraftTimer=null, campoAtlasContextData=null;

function itaOpenFieldDB(){return new Promise((resolve,reject)=>{if(campoDB)return resolve(campoDB);const req=indexedDB.open(ITA_FIELD_DB,1);req.onupgradeneeded=()=>{const db=req.result;if(!db.objectStoreNames.contains(ITA_FIELD_STORE)){const s=db.createObjectStore(ITA_FIELD_STORE,{keyPath:'id'});s.createIndex('campanha','campanha',{unique:false});s.createIndex('created_at','created_at',{unique:false})}};req.onsuccess=()=>{campoDB=req.result;resolve(campoDB)};req.onerror=()=>reject(req.error)})}
function itaId(){return 'ITA-REC-'+new Date().toISOString().replace(/[-:.TZ]/g,'').slice(0,14)+'-'+Math.random().toString(36).slice(2,7).toUpperCase()}
function itaSpotId(){return 'ITA-SPOT-'+new Date().toISOString().replace(/[-:.TZ]/g,'').slice(0,14)+'-'+Math.random().toString(36).slice(2,6).toUpperCase()}
function itaVal(id){return document.getElementById(id)?.value?.trim?.()||''}
function itaSetVal(id,v){const e=document.getElementById(id);if(e)e.value=v??''}
function itaTags(){return itaVal('campoTags').split(',').map(x=>x.trim()).filter(Boolean).filter((x,i,a)=>a.indexOf(x)===i)}
function itaCampoDateKey(){const d=new Date(),p=n=>String(n).padStart(2,'0');return `${d.getFullYear()}${p(d.getMonth()+1)}${p(d.getDate())}`}
function itaCampoNextStationCode(){const day=itaCampoDateKey(),key='ita_arandu_campo_station_seq_'+day;let n=Number(localStorage.getItem(key)||0)+1;localStorage.setItem(key,String(n));return `ITA-CAMPO-${day}-${String(n).padStart(3,'0')}`}
function itaCampoSampleCode(index){const st=itaVal('campoStationCode')||'ITA-CAMPO';return `${st}-A${String(index+1).padStart(2,'0')}`}
function itaCampoMeasureCode(index){const st=itaVal('campoStationCode')||'ITA-CAMPO';return `${st}-M${String(index+1).padStart(2,'0')}`}
function itaCampoPhotoCode(index){const st=itaVal('campoStationCode')||'ITA-CAMPO';return `${st}-P${String(index+1).padStart(2,'0')}`}

function itaPointInRing(lon,lat,ring){let inside=false;for(let i=0,j=ring.length-1;i<ring.length;j=i++){const xi=ring[i][0],yi=ring[i][1],xj=ring[j][0],yj=ring[j][1];const hit=((yi>lat)!=(yj>lat))&&(lon<(xj-xi)*(lat-yi)/((yj-yi)||1e-15)+xi);if(hit)inside=!inside}return inside}
function itaPointInGeom(lon,lat,g){if(!g)return false;if(g.type==='Polygon')return g.coordinates.length&&itaPointInRing(lon,lat,g.coordinates[0]);if(g.type==='MultiPolygon')return g.coordinates.some(p=>p.length&&itaPointInRing(lon,lat,p[0]));return false}
function itaFindFeatureAt(layerId,lon,lat){const fc=window.ATLAS_DATA?.[layerId];if(!fc?.features)return null;for(const f of fc.features){if(itaPointInGeom(lon,lat,f.geometry))return f}return null}
function itaFindHex(layerId,lon,lat){const f=itaFindFeatureAt(layerId,lon,lat);return f?.properties?.hex_id||f?.properties?.id||''}

function itaCampoSetNow(){const d=new Date(),pad=n=>String(n).padStart(2,'0');if(!itaVal('campoData'))itaSetVal('campoData',`${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}`);if(!itaVal('campoHora'))itaSetVal('campoHora',`${pad(d.getHours())}:${pad(d.getMinutes())}`);if(!itaVal('campoSpotId'))itaSetVal('campoSpotId',itaSpotId())}
function itaCampoApplyStationCode(code){itaSetVal('campoStationCode',code);itaSetVal('campoStationCodeView',code);const disp=document.getElementById('campoStationDisplay'),head=document.getElementById('campoHeadCode');if(disp)disp.textContent=code||'—';if(head)head.textContent=code||'Nova estação'}
function itaCampoNewStation(keepIdentity=true){const identity=keepIdentity?{campanha:itaVal('campoCampanha'),observador:itaVal('campoObservador'),disciplina:itaVal('campoDisciplina')}:{};document.getElementById('campoForm')?.reset();itaCampoApplyStationCode(itaCampoNextStationCode());itaSetVal('campoEditingRecordId','');itaSetVal('campoCampanha',identity.campanha||'');itaSetVal('campoObservador',identity.observador||'');itaSetVal('campoDisciplina',identity.disciplina||'');itaSetVal('campoSpotId',itaSpotId());itaSetVal('campoValidationStatus','RASCUNHO');itaSetVal('campoSensibilidade','local');itaSetVal('campoAcessoStatus','nao_avaliado');itaSetVal('campoColetaStatus','nao_avaliado');campoMeasures=[];campoSamples=[];campoSelectedFiles=[];campoPhotoMeta=[];campoAtlasContextData=null;document.getElementById('campoFotoPreview').innerHTML='';itaCampoRenderMeasures();itaCampoRenderSamples();itaCampoRenderContext();itaCampoSetNow();itaCampoSetMode('completo');itaCampoGoStep(1);localStorage.removeItem(ITA_FIELD_DRAFT);itaCampoSaveDraft();document.getElementById('campoStatus').textContent='Nova estação criada. O rascunho será salvo automaticamente.'}

function itaCampoSetMode(mode){campoMode=['rapido','completo','aprender'].includes(mode)?mode:'completo';document.querySelectorAll('.campo-mode').forEach(b=>b.classList.toggle('active',b.dataset.campoMode===campoMode));document.querySelectorAll('#campoStepper [data-campo-step]').forEach(b=>{const s=Number(b.dataset.campoStep);b.hidden=campoMode==='rapido'&&(s===4||s===5)});itaCampoLearningPrompt();itaCampoScheduleDraft()}
function itaCampoSequence(){return campoMode==='rapido'?[1,2,3,6,7,8]:[1,2,3,4,5,6,7,8]}
function itaCampoGoStep(step){const seq=itaCampoSequence();if(!seq.includes(Number(step)))step=seq[0];campoCurrentStep=Number(step);document.querySelectorAll('.campo-step').forEach(s=>s.classList.toggle('active',Number(s.dataset.fieldStep)===campoCurrentStep));let activeStepBtn=null;document.querySelectorAll('#campoStepper [data-campo-step]').forEach(b=>{const n=Number(b.dataset.campoStep);b.classList.toggle('active',n===campoCurrentStep);b.classList.toggle('done',seq.indexOf(n)>=0&&seq.indexOf(n)<seq.indexOf(campoCurrentStep));if(n===campoCurrentStep)activeStepBtn=b});if(activeStepBtn&&window.matchMedia('(max-width:760px)').matches){const nav=activeStepBtn.parentElement;if(nav)nav.scrollTo({left:Math.max(0,activeStepBtn.offsetLeft-(nav.clientWidth-activeStepBtn.clientWidth)/2),behavior:'smooth'})}if(campoCurrentStep===8)itaCampoRenderReview();itaCampoLearningPrompt();const modal=document.querySelector('#campoModal .modal-box');if(modal)modal.scrollTop=0;itaCampoScheduleDraft()}
function itaCampoPrev(){const seq=itaCampoSequence(),i=seq.indexOf(campoCurrentStep);if(i>0)itaCampoGoStep(seq[i-1])}
function itaCampoNext(){const seq=itaCampoSequence(),i=seq.indexOf(campoCurrentStep);if(i>=0&&i<seq.length-1)itaCampoGoStep(seq[i+1]);else itaCampoGoStep(8)}
function itaCampoLearningPrompt(){const box=document.getElementById('campoLearningPrompt');if(!box)return;if(campoMode!=='aprender'){box.hidden=true;return}const prompts={1:'Identifique quem observa, quando e em qual campanha. Rastreabilidade começa antes da interpretação.',2:'Qual é a precisão da sua posição? Coordenada de mapa não é medição GPS.',3:'Descreva antes de nomear ou explicar. O que realmente está visível?',4:'Quais características macroscópicas sustentam sua identificação litológica?',5:'Uma medida estrutural é um dado independente. Registre orientação, método e qualidade.',6:'Toda amostra deve poder voltar à estação onde foi coletada. Não reutilize códigos.',7:'Que evidências sustentam sua interpretação? Existe hipótese alternativa?',8:'O que está incompleto? O que esta estação permite afirmar e o que ainda não permite?'};box.hidden=false;box.innerHTML='<b>Modo Aprender</b> · '+(prompts[campoCurrentStep]||'Observe, registre e questione.')}

function itaCampoLitoPanels(){const g=itaVal('campoGrupoRocha');document.querySelectorAll('.campo-lito-panel').forEach(x=>x.hidden=x.dataset.lito!==g)}
function itaIdentifyGrids(){const lat=Number(itaVal('campoLat')),lon=Number(itaVal('campoLon'));const status=document.getElementById('campoGpsStatus');if(!Number.isFinite(lat)||!Number.isFinite(lon)){if(status)status.textContent='Informe latitude e longitude antes de identificar o contexto.';return}const a=itaFindHex('malha_r5_250km2',lon,lat),b=itaFindHex('malha_500km2',lon,lat),c=itaFindHex('malha_1000km2',lon,lat);itaSetVal('campoHex250',a);itaSetVal('campoHex500',b);itaSetVal('campoHex1000',c);const geo=itaFindFeatureAt('mapa_geologico_ms',lon,lat),mun=itaFindFeatureAt('limites_municipais_ibge_2025',lon,lat);const gp=geo?.properties||{},mp=mun?.properties||{};const munName=mp.NM_MUN||mp.nome||mp.NOME||mp.name||'';if(munName&&!itaVal('campoMunicipio'))itaSetVal('campoMunicipio',munName);campoAtlasContextData={hex_250:a||null,hex_500:b||null,hex_1000:c||null,geologia:geo?{nome:gp.NOME||gp.nome||null,sigla:gp.SIGLA||gp.sigla||null,escala:gp.ESCALA||null,mapa:gp.MAPA||null}:null,municipio:munName||itaVal('campoMunicipio')||null};itaCampoRenderContext();if(status)status.textContent=`Contexto identificado · 250 ${a||'fora'} · 500 ${b||'fora'} · 1000 ${c||'fora'}`;itaCampoScheduleDraft()}
function itaCampoRenderContext(){const box=document.getElementById('campoAtlasContext');if(!box)return;if(!campoAtlasContextData){box.innerHTML='<b>Contexto do Atlas</b><span>Capture uma posição para consultar unidade geológica, município e malhas. Este bloco é contexto cartográfico e <u>não constitui observação de campo</u>.</span>';return}const g=campoAtlasContextData.geologia;box.innerHTML=`<b>Contexto do Atlas · não é observação</b><span>${g?`Mapa geológico · ${esc(g.sigla||'')} ${esc(g.nome||'unidade sem nome')} · escala ${esc(g.escala||'não informada')}`:'Unidade geológica não identificada no snapshot carregado.'}<br>Município · ${esc(campoAtlasContextData.municipio||'não identificado')}<br>Malhas · 250 ${esc(campoAtlasContextData.hex_250||'—')} · 500 ${esc(campoAtlasContextData.hex_500||'—')} · 1000 ${esc(campoAtlasContextData.hex_1000||'—')}</span>`}

function itaCampoAddMeasure(data={}){const i=campoMeasures.length;campoMeasures.push({code:data.code||itaCampoMeasureCode(i),type:data.type||'',azimuth:data.azimuth??'',dip:data.dip??'',dip_direction:data.dip_direction??'',trend:data.trend??'',plunge:data.plunge??'',method:data.method||'bússola geológica',quality:data.quality||'não avaliada',note:data.note||''});itaCampoRenderMeasures();itaCampoScheduleDraft()}
function itaCampoRenderMeasures(){const box=document.getElementById('campoMedidasLista');if(!box)return;if(!campoMeasures.length){box.innerHTML='<div class="empty">Nenhuma medida registrada.</div>';return}box.innerHTML=campoMeasures.map((m,i)=>`<div class="campo-object-card" data-measure="${i}"><div class="campo-object-title"><div><b>Medida ${i+1}</b> <code>${esc(m.code)}</code></div><div class="campo-mini-actions"><button type="button" class="campo-mini danger" data-remove-measure="${i}">Remover</button></div></div><div class="field-grid three"><label><span class="field-label">Tipo</span><select class="field-select" data-mfield="type"><option value="">Selecionar</option>${['Plano','Acamamento','Foliação','Fratura','Falha','Veio','Lineação','Eixo de dobra','Outro'].map(v=>`<option ${m.type===v?'selected':''}>${v}</option>`).join('')}</select></label><label><span class="field-label">Azimute / direção 0–360°</span><input class="field-input" type="number" min="0" max="360" step="0.1" data-mfield="azimuth" value="${esc(String(m.azimuth))}"></label><label><span class="field-label">Mergulho 0–90°</span><input class="field-input" type="number" min="0" max="90" step="0.1" data-mfield="dip" value="${esc(String(m.dip))}"></label><label><span class="field-label">Direção do mergulho</span><input class="field-input" type="number" min="0" max="360" step="0.1" data-mfield="dip_direction" value="${esc(String(m.dip_direction))}"></label><label><span class="field-label">Trend</span><input class="field-input" type="number" min="0" max="360" step="0.1" data-mfield="trend" value="${esc(String(m.trend))}"></label><label><span class="field-label">Plunge 0–90°</span><input class="field-input" type="number" min="0" max="90" step="0.1" data-mfield="plunge" value="${esc(String(m.plunge))}"></label><label><span class="field-label">Método</span><input class="field-input" data-mfield="method" value="${esc(m.method)}"></label><label><span class="field-label">Qualidade</span><select class="field-select" data-mfield="quality">${['não avaliada','baixa','moderada','boa','alta'].map(v=>`<option ${m.quality===v?'selected':''}>${v}</option>`).join('')}</select></label><label><span class="field-label">Nota</span><input class="field-input" data-mfield="note" value="${esc(m.note)}"></label></div></div>`).join('')}
function itaCampoMeasureInput(e){const card=e.target.closest('[data-measure]');if(!card)return;const i=Number(card.dataset.measure),field=e.target.dataset.mfield;if(field&&campoMeasures[i]){campoMeasures[i][field]=e.target.value;itaCampoScheduleDraft()}}

function itaCampoAddSample(data={}){const i=campoSamples.length;campoSamples.push({code:data.code||itaCampoSampleCode(i),material:data.material||'',purpose:data.purpose||'',container:data.container||'',description:data.description||'',igsn_id:data.igsn_id||'',igsn_status:data.igsn_status||'nao_registrado',mass:data.mass||'',notes:data.notes||''});itaCampoRenderSamples();itaCampoScheduleDraft()}
function itaCampoRenderSamples(){const box=document.getElementById('campoAmostrasLista');if(!box)return;if(!campoSamples.length){box.innerHTML='<div class="empty">Nenhuma amostra coletada.</div>';return}box.innerHTML=campoSamples.map((s,i)=>`<div class="campo-object-card" data-sample="${i}"><div class="campo-object-title"><div><b>Amostra ${i+1}</b> <code>${esc(s.code)}</code></div><div class="campo-mini-actions"><button type="button" class="campo-mini" data-copy-sample="${i}">Copiar código</button><button type="button" class="campo-mini" data-print-sample="${i}">Etiqueta</button><button type="button" class="campo-mini danger" data-remove-sample="${i}">Remover</button></div></div><div class="field-grid three"><label><span class="field-label">Material / tipo</span><input class="field-input" data-sfield="material" value="${esc(s.material)}" placeholder="rocha, solo, sedimento, água..."></label><label><span class="field-label">Finalidade</span><input class="field-input" data-sfield="purpose" value="${esc(s.purpose)}" placeholder="petrografia, geoquímica..."></label><label><span class="field-label">Recipiente / saco</span><input class="field-input" data-sfield="container" value="${esc(s.container)}"></label><label><span class="field-label">Massa / volume aproximado</span><input class="field-input" data-sfield="mass" value="${esc(s.mass)}"></label><label><span class="field-label">IGSN ID</span><input class="field-input" data-sfield="igsn_id" value="${esc(s.igsn_id)}" placeholder="somente se existir"></label><label><span class="field-label">Estado IGSN</span><select class="field-select" data-sfield="igsn_status"><option value="nao_registrado" ${s.igsn_status==='nao_registrado'?'selected':''}>Não registrado</option><option value="informado_validar" ${s.igsn_status==='informado_validar'?'selected':''}>Informado · validar</option><option value="registrado" ${s.igsn_status==='registrado'?'selected':''}>Registrado</option></select></label><label class="field-full"><span class="field-label">Descrição da amostra</span><input class="field-input" data-sfield="description" value="${esc(s.description)}"></label><label class="field-full"><span class="field-label">Notas</span><input class="field-input" data-sfield="notes" value="${esc(s.notes)}"></label></div></div>`).join('')}
function itaCampoSampleInput(e){const card=e.target.closest('[data-sample]');if(!card)return;const i=Number(card.dataset.sample),field=e.target.dataset.sfield;if(field&&campoSamples[i]){campoSamples[i][field]=e.target.value;itaCampoScheduleDraft()}}
async function itaCampoCopySample(i){const code=campoSamples[i]?.code;if(!code)return;try{await navigator.clipboard.writeText(code);document.getElementById('campoStatus').textContent=`Código copiado · ${code}`}catch{document.getElementById('campoStatus').textContent=`Código da amostra · ${code}`}}
function itaCampoPrintSample(i){const s=campoSamples[i];if(!s)return;const code=s.code,lat=itaVal('campoLat'),lon=itaVal('campoLon'),date=itaVal('campoData');const w=window.open('','_blank','width=620,height=430');if(!w)return;w.document.write(`<!doctype html><meta charset="utf-8"><title>${esc(code)}</title><style>body{font-family:Arial;padding:24px}.label{border:3px solid #111;padding:18px;width:480px}.code{font:900 25px monospace;margin:10px 0}.meta{font-size:13px;line-height:1.6}@media print{button{display:none}}</style><div class="label"><b>ITA ARANDU MS · AMOSTRA</b><div class="code">${esc(code)}</div><div class="meta">Estação · ${esc(itaVal('campoStationCode'))}<br>Data · ${esc(date||'—')}<br>Material · ${esc(s.material||'—')}<br>Finalidade · ${esc(s.purpose||'—')}<br>Localização · ${esc(lat||'—')}, ${esc(lon||'—')}</div></div><p><button onclick="print()">Imprimir etiqueta</button></p>`);w.document.close()}

function itaPreviewFiles(files){campoSelectedFiles=[...files].slice(0,20);campoPhotoMeta=campoSelectedFiles.map((f,i)=>({id:itaCampoPhotoCode(i),category:'afloramento',caption:'',name:f.name,type:f.type,size:f.size,lastModified:f.lastModified}));itaCampoRenderPhotos();itaCampoScheduleDraft()}
function itaCampoRenderPhotos(){const box=document.getElementById('campoFotoPreview');if(!box)return;box.innerHTML='';campoSelectedFiles.forEach((f,i)=>{const m=campoPhotoMeta[i]||{};const card=document.createElement('div');card.className='campo-photo-card';card.dataset.photo=i;const img=document.createElement('img');img.alt=f.name;img.src=URL.createObjectURL(f);const meta=document.createElement('div');meta.className='campo-photo-meta';meta.innerHTML=`<code>${esc(m.id||itaCampoPhotoCode(i))}</code><select data-pfield="category">${['panorama','afloramento','detalhe','estrutura','amostra','escala','outro'].map(v=>`<option ${m.category===v?'selected':''}>${v}</option>`).join('')}</select><input data-pfield="caption" value="${esc(m.caption||'')}" placeholder="Legenda / orientação / detalhe">`;card.append(img,meta);box.appendChild(card)})}
function itaCampoPhotoInput(e){const card=e.target.closest('[data-photo]');if(!card)return;const i=Number(card.dataset.photo),field=e.target.dataset.pfield;if(field&&campoPhotoMeta[i]){campoPhotoMeta[i][field]=e.target.value;itaCampoScheduleDraft()}}

function itaCampoGetFormValues(){const vals={};document.querySelectorAll('#campoForm input[id],#campoForm select[id],#campoForm textarea[id]').forEach(e=>{if(e.type!=='file')vals[e.id]=e.value});return vals}
function itaCampoDraftPayload(){return{schema_version:'0.4',saved_at:new Date().toISOString(),mode:campoMode,step:campoCurrentStep,values:itaCampoGetFormValues(),measures:campoMeasures,samples:campoSamples,photo_meta:campoPhotoMeta,atlas_context:campoAtlasContextData}}
function itaCampoSaveDraft(){try{localStorage.setItem(ITA_FIELD_DRAFT,JSON.stringify(itaCampoDraftPayload()));const s=document.getElementById('campoDraftStatus');if(s)s.textContent='Rascunho salvo · '+new Date().toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'});}catch{}}
function itaCampoScheduleDraft(){clearTimeout(campoDraftTimer);campoDraftTimer=setTimeout(itaCampoSaveDraft,350)}
function itaCampoRestoreDraft(){try{const raw=localStorage.getItem(ITA_FIELD_DRAFT);if(!raw)return false;const d=JSON.parse(raw);if(!d?.values?.campoStationCode)return false;Object.entries(d.values).forEach(([k,v])=>itaSetVal(k,v));itaCampoApplyStationCode(d.values.campoStationCode);campoMeasures=Array.isArray(d.measures)?d.measures:[];campoSamples=Array.isArray(d.samples)?d.samples:[];campoPhotoMeta=Array.isArray(d.photo_meta)?d.photo_meta:[];campoSelectedFiles=[];campoAtlasContextData=d.atlas_context||null;itaCampoRenderMeasures();itaCampoRenderSamples();itaCampoRenderPhotos();itaCampoRenderContext();itaCampoLitoPanels();itaCampoSetMode(d.mode||'completo');itaCampoGoStep(d.step||1);document.getElementById('campoStatus').textContent='Rascunho textual recuperado. Fotografias precisam ser selecionadas novamente após recarregar a página.';return true}catch{return false}}

function itaCampoValidationIssues(){const issues=[];const lat=Number(itaVal('campoLat')),lon=Number(itaVal('campoLon'));if(!itaVal('campoObservador'))issues.push('Observador não informado.');if(!itaVal('campoData'))issues.push('Data não informada.');if(!Number.isFinite(lat)||!Number.isFinite(lon))issues.push('Localização geográfica ausente ou inválida.');if(!itaVal('campoExposicao'))issues.push('Tipo de exposição não selecionado.');if(!itaVal('campoObservacao'))issues.push('Observação direta ainda vazia.');if(!itaVal('campoLitologia')&&campoMode!=='rapido')issues.push('Litologia não preenchida; mantenha vazio se realmente não foi possível identificar.');campoMeasures.forEach((m,i)=>{for(const [k,max] of [['azimuth',360],['dip_direction',360],['trend',360],['dip',90],['plunge',90]]){if(m[k]!==''&&(Number(m[k])<0||Number(m[k])>max||!Number.isFinite(Number(m[k]))))issues.push(`Medida ${i+1}: ${k} fora do intervalo válido.`)}});campoSamples.forEach((s,i)=>{if(s.igsn_status==='registrado'&&!s.igsn_id)issues.push(`Amostra ${i+1}: IGSN marcado como registrado sem identificador.`)});return issues}
function itaCampoRenderReview(){const issues=itaCampoValidationIssues(),ib=document.getElementById('campoReviewIssues'),sb=document.getElementById('campoReviewSummary');if(ib)ib.innerHTML=issues.length?issues.map(x=>`<div class="issue">${esc(x)}</div>`).join(''):'<div class="issue ok">Nenhuma inconsistência básica detectada. Revise o conteúdo científico antes de aprovar.</div>';if(sb){const g=campoAtlasContextData?.geologia;sb.innerHTML=`<div class="campo-review-block"><b>Estação</b><code>${esc(itaVal('campoStationCode'))}</code><br>${esc(itaVal('campoNome')||'sem nome')} · ${esc(itaVal('campoData')||'sem data')} · ${esc(itaVal('campoObservador')||'sem observador')}</div><div class="campo-review-block"><b>Localização</b>${esc(itaVal('campoLat')||'—')}, ${esc(itaVal('campoLon')||'—')} · precisão ${esc(itaVal('campoPrecisao')||'—')} m<br>Hex 250 · ${esc(itaVal('campoHex250')||'—')}</div><div class="campo-review-block"><b>Contexto cartográfico</b>${g?`${esc(g.sigla||'')} ${esc(g.nome||'')} · ${esc(g.escala||'')}`:'não identificado'}<br><em>Não constitui observação de campo.</em></div><div class="campo-review-block"><b>Objetos associados</b>${campoMeasures.length} medida(s) · ${campoSamples.length} amostra(s) · ${campoSelectedFiles.length} fotografia(s)</div><div class="campo-review-block"><b>Observação</b>${esc((itaVal('campoObservacao')||'—').slice(0,350))}</div><div class="campo-review-block"><b>Interpretação</b>${esc((itaVal('campoInterpretacao')||'—').slice(0,350))}<br>Confiança · ${esc(itaVal('campoConfiancaInterpretacao')||'não avaliada')}</div>`}}

