function itaPaleoEls(){return{lat:document.getElementById('paleoLat'),lon:document.getElementById('paleoLon'),model:document.getElementById('paleoModel'),age:document.getElementById('paleoAge'),ageN:document.getElementById('paleoAgeNumber'),status:document.getElementById('paleoStatus'),now:document.getElementById('paleoNowResult'),old:document.getElementById('paleoOldResult'),time:document.getElementById('paleoTimeResult'),modelR:document.getElementById('paleoModelResult'),modelNote:document.getElementById('paleoModelNote'),origin:document.getElementById('paleoOriginLabel'),canvas:document.getElementById('paleoCanvas'),source:document.getElementById('paleoSourceText')}}
function itaPaleoModelMax(){const e=itaPaleoEls(),o=e.model?.selectedOptions?.[0];return Number(o?.dataset?.max||ITA_PAL_MODELS[e.model?.value]?.max||410)}
function itaPaleoAgeLabel(age){age=Number(age);const p=(window.ITA_ICS?.periods||[]).find(x=>age<=Number(x.begin)&&age>=Number(x.end));if(p)return `${p.label} · ${age.toLocaleString('pt-BR')} Ma`;const er=(window.ITA_ICS?.eras||[]).find(x=>age<=Number(x.begin)&&age>=Number(x.end));if(er)return `${er.label} · ${age.toLocaleString('pt-BR')} Ma`;const eo=(window.ITA_ICS?.eons||[]).find(x=>age<=Number(x.begin)&&age>=Number(x.end));return `${eo?.label||'Tempo profundo'} · ${age.toLocaleString('pt-BR')} Ma`}
function itaPaleoSetAge(v){const e=itaPaleoEls(),max=itaPaleoModelMax();v=Math.max(0,Math.min(max,Number(v)||0));if(e.age){e.age.max=max;e.age.value=v}if(e.ageN){e.ageN.max=max;e.ageN.value=v}if(e.time)e.time.textContent=itaPaleoAgeLabel(v)}
function itaPaleoSyncModel(){const e=itaPaleoEls(),max=itaPaleoModelMax();if(e.modelNote)e.modelNote.textContent=`Intervalo publicado do modelo selecionado · 0–${max.toLocaleString('pt-BR')} Ma.`;itaPaleoSetAge(Math.min(Number(e.ageN?.value||100),max));if(e.modelR)e.modelR.textContent=e.model?.value||'—'}
function itaPaleoCurrentCoords(){const e=itaPaleoEls(),lat=Number(e.lat?.value),lon=Number(e.lon?.value);if(!Number.isFinite(lat)||lat<-90||lat>90||!Number.isFinite(lon)||lon<-180||lon>180)throw new Error('Informe latitude entre −90 e 90 e longitude entre −180 e 180.');return{lat,lon}}
function itaPaleoFmtCoord(lat,lon){const ns=lat<0?'S':'N',ew=lon<0?'W':'E';return `${Math.abs(lat).toFixed(4)}° ${ns} · ${Math.abs(lon).toFixed(4)}° ${ew}`}
function itaPaleoProject(lon,lat,w,h){return[(Number(lon)+180)/360*w,(90-Number(lat))/180*h]}
function itaPaleoDrawBase(current=null,paleo=null,coasts=null){const e=itaPaleoEls(),c=e.canvas;if(!c)return;const ctx=c.getContext('2d'),w=c.width,h=c.height;ctx.clearRect(0,0,w,h);ctx.fillStyle='#edf4f6';ctx.fillRect(0,0,w,h);ctx.strokeStyle='#d2e0e7';ctx.lineWidth=1;for(let lon=-150;lon<=150;lon+=30){const[x]=itaPaleoProject(lon,0,w,h);ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,h);ctx.stroke()}for(let lat=-60;lat<=60;lat+=30){const[,y]=itaPaleoProject(0,lat,w,h);ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(w,y);ctx.stroke()}ctx.strokeStyle='#8aa6b5';ctx.lineWidth=1.1;const drawLine=coords=>{if(!Array.isArray(coords)||coords.length<2)return;ctx.beginPath();let prev=null;for(const pt of coords){if(!Array.isArray(pt)||pt.length<2)continue;const q=itaPaleoProject(pt[0],pt[1],w,h);if(!prev||Math.abs(q[0]-prev[0])>w*.5)ctx.moveTo(q[0],q[1]);else ctx.lineTo(q[0],q[1]);prev=q}ctx.stroke()};if(coasts?.features)for(const f of coasts.features){const g=f.geometry;if(!g)continue;if(g.type==='LineString')drawLine(g.coordinates);else if(g.type==='MultiLineString')g.coordinates.forEach(drawLine);else if(g.type==='Polygon')g.coordinates.forEach(drawLine);else if(g.type==='MultiPolygon')g.coordinates.forEach(p=>p.forEach(drawLine))}const dot=(pt,color,r,label)=>{if(!pt)return;const[x,y]=itaPaleoProject(pt.lon,pt.lat,w,h);ctx.beginPath();ctx.arc(x,y,r,0,Math.PI*2);ctx.fillStyle=color;ctx.fill();ctx.strokeStyle='#fff';ctx.lineWidth=2;ctx.stroke();ctx.font='bold 18px system-ui';ctx.fillStyle='#183d55';ctx.fillText(label,Math.min(w-120,x+10),Math.max(20,y-8))};dot(current,'#0b67a3',7,'atual');dot(paleo,'#d87b22',8,'paleo');ctx.strokeStyle='#9fb4bf';ctx.strokeRect(.5,.5,w-1,h-1)}
async function itaFetchJson(url,timeout=16000){const c=new AbortController(),t=setTimeout(()=>c.abort(),timeout);try{const r=await fetch(url,{signal:c.signal,cache:'no-store'});if(!r.ok)throw new Error(`serviço respondeu ${r.status}`);return await r.json()}finally{clearTimeout(t)}}
async function itaPaleoRun(){const e=itaPaleoEls();try{const cur=itaPaleoCurrentCoords(),age=Number(e.ageN?.value||0),model=e.model?.value||'ZAHIROVIC2022',max=itaPaleoModelMax();if(age>max)throw new Error(`O modelo ${model} termina em ${max} Ma. Escolha outro modelo ou reduza a idade.`);e.status.textContent='Consultando paleoposição no GPlates Web Service…';e.now.textContent=itaPaleoFmtCoord(cur.lat,cur.lon);e.old.textContent='consultando';e.time.textContent=itaPaleoAgeLabel(age);e.modelR.textContent=model;itaPaleoDrawBase(cur,null,null);const u=`https://gws.gplates.org/reconstruct/reconstruct_points/?lats=${encodeURIComponent(cur.lat)}&lons=${encodeURIComponent(cur.lon)}&time=${encodeURIComponent(age)}&model=${encodeURIComponent(model)}&fc`;const j=await itaFetchJson(u,18000),coords=j?.features?.[0]?.geometry?.coordinates;if(!Array.isArray(coords)||coords.length<2||Math.abs(Number(coords[0]))>180||Math.abs(Number(coords[1]))>90)throw new Error('O modelo não devolveu uma paleoposição válida para esse ponto e essa idade.');const pal={lon:Number(coords[0]),lat:Number(coords[1])};e.old.textContent=itaPaleoFmtCoord(pal.lat,pal.lon);e.status.textContent=`Paleoposição calculada com ${model} para ${age.toLocaleString('pt-BR')} Ma. Carregando costas reconstruídas para contexto…`;itaPaleoDrawBase(cur,pal,null);const cu=`https://gws.gplates.org/reconstruct/coastlines/?time=${encodeURIComponent(age)}&model=${encodeURIComponent(model)}`;try{const coast=await itaFetchJson(cu,20000);itaPaleoDrawBase(cur,pal,coast);e.status.textContent=`Reconstrução concluída · ${itaPaleoAgeLabel(age)} · ${model}.`;e.source.textContent=`Fonte de cálculo e costas reconstruídas · GPlates Web Service · ${model}. A paleoposição é resultado de modelo. Os pontos atual e reconstruído são comparados no mesmo sistema gráfico e não representam uma trajetória física.`}catch(coastErr){itaPaleoDrawBase(cur,pal,null);e.status.textContent=`Paleoposição concluída. As costas reconstruídas não puderam ser carregadas agora · ${coastErr.message}.`;e.source.textContent=`Fonte da paleoposição · GPlates Web Service · ${model}. O mapa permanece esquemático porque o serviço de costas não respondeu.`}}catch(err){e.status.textContent=`Não foi possível reconstruir · ${err?.name==='AbortError'?'tempo de resposta excedido':err.message}. O restante do Atlas continua funcional.`;e.old.textContent='sem resultado'}}
