// V33 Beta · PWA instalável e base para Android Trusted Web Activity
let itaPwaInstallPrompt = null;
function itaPwaStandalone(){
  return window.matchMedia?.('(display-mode: standalone)')?.matches || window.navigator.standalone === true;
}
function itaPwaStatus(message){
  const el=document.getElementById('pwaInstallStatus');
  if(el)el.textContent=message;
}
function itaPwaRefreshState(){
  const btn=document.getElementById('pwaInstallBtn');
  if(!btn)return;
  if(itaPwaStandalone()){
    btn.disabled=true;
    btn.textContent='Aplicativo instalado';
    itaPwaStatus('ITA ARANDU MS está sendo executado em modo de aplicativo instalado.');
    return;
  }
  if(itaPwaInstallPrompt){
    btn.disabled=false;
    btn.textContent='Instalar ITA ARANDU MS';
    itaPwaStatus('Instalação disponível. Toque em Instalar ITA ARANDU MS.');
    return;
  }
  btn.disabled=false;
  btn.textContent='Como instalar';
  itaPwaStatus('Se o navegador não mostrar a instalação automática, abra o menu do navegador e escolha Instalar app ou Adicionar à tela inicial. A página precisa estar publicada por HTTPS.');
}
window.addEventListener('beforeinstallprompt',event=>{
  event.preventDefault();
  itaPwaInstallPrompt=event;
  itaPwaRefreshState();
});
window.addEventListener('appinstalled',()=>{
  itaPwaInstallPrompt=null;
  itaPwaRefreshState();
});
document.getElementById('pwaInstallBtn')?.addEventListener('click',async()=>{
  if(itaPwaStandalone())return;
  if(!itaPwaInstallPrompt){
    itaPwaStatus('Use o menu do navegador e escolha Instalar app ou Adicionar à tela inicial. Em Android recomendamos abrir a versão publicada no Chrome.');
    return;
  }
  const prompt=itaPwaInstallPrompt;
  itaPwaInstallPrompt=null;
  await prompt.prompt();
  try{
    const choice=await prompt.userChoice;
    itaPwaStatus(choice?.outcome==='accepted'?'Instalação aceita pelo dispositivo.':'Instalação não concluída. Você pode tentar novamente pelo menu do navegador.');
  }catch(_){
    itaPwaStatus('O pedido de instalação foi enviado ao dispositivo.');
  }
  itaPwaRefreshState();
});
document.getElementById('pwaReloadBtn')?.addEventListener('click',async()=>{
  itaPwaStatus('Verificando atualização do aplicativo.');
  try{
    const reg=await navigator.serviceWorker?.getRegistration();
    if(reg)await reg.update();
  }catch(_){ }
  window.location.reload();
});
document.querySelectorAll('[data-modal="pwaModal"]').forEach(b=>b.addEventListener('click',()=>setTimeout(itaPwaRefreshState,0)));
if('serviceWorker' in navigator && location.protocol!=='file:'){
  window.addEventListener('load',()=>navigator.serviceWorker.register('./service-worker.js?v=38.4.38',{scope:'./',updateViaCache:'none'}).then(()=>itaPwaRefreshState()).catch(err=>itaPwaStatus('A instalação PWA não pôde ser ativada neste acesso. '+err.message)));
}else{
  itaPwaRefreshState();
}

// PATCH 09 · Modo Aprender
window.ITA_APRENDER_POSITION=window.ITA_APRENDER_POSITION||null;
function itaAprenderInsideMs(lat,lon){
 return lat>=MS_BOUNDS.minLat&&lat<=MS_BOUNDS.maxLat&&lon>=MS_BOUNDS.minLon&&lon<=MS_BOUNDS.maxLon
}
function itaAprenderLocate(){
 const status=document.getElementById('aprenderLocationStatus'),view=document.getElementById('aprenderViewMap');
 if(!status)return;
 if(!navigator.geolocation){
  status.textContent='Este navegador não disponibiliza geolocalização.';
  return;
 }
 status.textContent='Solicitando posição ao dispositivo. O navegador poderá pedir permissão.';
 if(view)view.disabled=true;
 navigator.geolocation.getCurrentPosition(pos=>{
  const lat=pos.coords.latitude,lon=pos.coords.longitude,acc=Math.max(1,Math.round(pos.coords.accuracy||0));
  window.ITA_APRENDER_POSITION={lat,lon,accuracy:acc,capturedAt:new Date().toISOString()};
  const area=itaAprenderInsideMs(lat,lon)?'posição dentro do recorte de Mato Grosso do Sul':'posição fora do recorte estadual do Atlas';
  status.innerHTML=`<b>Posição capturada</b> · ${lat.toFixed(6)}, ${lon.toFixed(6)} · precisão aproximada ${acc} m · ${area}.`;
  if(view)view.disabled=false;
 },err=>{
  status.textContent='Não foi possível obter a localização. Verifique a permissão do navegador e tente novamente.';
 },{enableHighAccuracy:true,timeout:15000,maximumAge:60000});
}
function itaAprenderShowPositionOnMap(){
 const p=window.ITA_APRENDER_POSITION;
 if(!p)return;
 itaSetGpsPosition(p.lat,p.lon,p.accuracy||20,{center:true,zoom:12});
 statusEl.textContent=`modo Aprender · localização ativa · precisão aproximada ${p.accuracy||0} m`;
 closeModal('aprenderModal');
 itaSetPrimaryNav('mapa');
}
function itaAprenderOpenCampo(showNotebook=false){
 closeModal('aprenderModal');
 openModal('campoModal');
 itaSetPrimaryNav('campo');
 itaSetNow();
 itaRenderFieldRecords();
 if(showNotebook)setTimeout(()=>document.getElementById('campoRegistros')?.scrollIntoView({behavior:'smooth',block:'start'}),180);
}
document.getElementById('aprenderLocate')?.addEventListener('click',itaAprenderLocate);
document.getElementById('aprenderViewMap')?.addEventListener('click',itaAprenderShowPositionOnMap);
document.getElementById('aprenderOpenCampo')?.addEventListener('click',()=>itaAprenderOpenCampo(false));
document.getElementById('aprenderOpenCaderno')?.addEventListener('click',()=>itaAprenderOpenCampo(true));
document.getElementById('aprenderOpenCampoFundamentos')?.addEventListener('click',()=>itaAprenderOpenCampo(false));
document.getElementById('aprenderOpenTempo')?.addEventListener('click',()=>{closeModal('aprenderModal');openModal('tempoModal');itaRenderTimePanels();itaSetPrimaryNav('aprender')});
document.getElementById('aprenderObserveMap')?.addEventListener('click',()=>{closeModal('aprenderModal');itaSetPrimaryNav('mapa');statusEl.textContent='Modo Aprender · observe o padrão antes de interpretar'});
document.querySelectorAll('[data-modal="aprenderModal"]').forEach(b=>b.addEventListener('click',()=>itaSetPrimaryNav('aprender')));
document.getElementById('openAprenderFromAjuda')?.addEventListener('click',()=>{
 closeModal('ajudaModal');
 openModal('aprenderModal');
 itaSetPrimaryNav('aprender');
});


/* V38 · DETETIVE DAS LACUNAS */
function itaFindHexById(data,id){return (data?.features||[]).find(f=>String(f.properties?.hex_id||'')===String(id))}
async function itaDetectiveActivateGrid(){const c=CATALOG.layers.find(x=>x.id==='malha_r5_250km2');if(c){await toggle(c.id,true);closeModal('aprenderModal');itaSetPrimaryNav('mapa');statusEl.textContent='Detetive das lacunas · selecione um hexágono da malha 250 km²'} }
async function itaDetectiveAnalyze(){const host=document.getElementById('detetiveResultado');if(!host)return;const id=state.selected?.feat?.properties?.hex_id;if(!id){host.innerHTML='<b>Selecione primeiro um hexágono de 250 km² no mapa.</b> Use o botão “Ativar malha 250 km²”, clique numa célula e volte a esta missão.';return}host.textContent='Consultando IMC e IPG desta célula...';try{const imcCfg=CATALOG.layers.find(x=>x.id==='imc_250'),ipgCfg=CATALOG.layers.find(x=>x.id==='ipg_r5_250km2');const imc=itaFindHexById(await ensure(imcCfg),id),ipg=itaFindHexById(await ensure(ipgCfg),id);const a=imc?.properties||{},b=ipg?.properties||{};const iv=Number.isFinite(Number(a.imc_100))?Number(a.imc_100).toFixed(1):'sem dado';const pv=Number.isFinite(Number(b.ipg_100))?Number(b.ipg_100).toFixed(1):'sem evidência suficiente';let leitura='Os dois indicadores descrevem dimensões diferentes do conhecimento e não devem ser confundidos.';if(Number.isFinite(Number(a.imc_100))&&Number(a.imc_100)<40&&!Number.isFinite(Number(b.ipg_100)))leitura='A célula combina baixa maturidade cartográfica e ausência de evidência suficiente no IPG. A conclusão correta é lacuna de conhecimento, não baixo interesse geológico.';else if(Number.isFinite(Number(a.imc_100))&&Number(a.imc_100)>=40&&!Number.isFinite(Number(b.ipg_100)))leitura='Há cobertura cartográfica relativamente mais madura, mas o inventário geocientífico ainda não sustenta IPG numérico. Pergunte que tipos de evidência faltam.';else if(Number.isFinite(Number(a.imc_100))&&Number(a.imc_100)<40&&Number.isFinite(Number(b.ipg_100)))leitura='Há evidência geocientífica documentada apesar da maturidade cartográfica limitada. Isso indica uma oportunidade clara de aprofundamento cartográfico.';window.ITA_DETETIVE_LAST={hex_id:id,imc_100:Number.isFinite(Number(a.imc_100))?Number(a.imc_100):null,classe_imc:a.classe_imc||null,ipg_100:Number.isFinite(Number(b.ipg_100))?Number(b.ipg_100):null,classe_ipg:b.classe_ipg||null,n_registros_ipg:b.n_registros??0,n_temas_ipg:b.n_temas??0,melhor_escala:a.melhor_escala_detectada||null,leitura};host.innerHTML=`<b>Hexágono ${esc(id)}</b><br><b>IMC</b> ${esc(iv)} · ${esc(a.classe_imc||'')}<br><b>IPG</b> ${esc(pv)} · ${esc(b.classe_ipg||'')}<br><b>Registros IPG</b> ${esc(b.n_registros??0)} · <b>temas</b> ${esc(b.n_temas??0)}<br><b>Escala detalhada identificada</b> ${esc(a.melhor_escala_detectada||'não informada')}<p>${esc(leitura)}</p><div class="aprender-principle"><b>Pergunta de investigação</b><span>Que evidência falta nesta célula e que levantamento permitiria testá-la sem confundir ausência de dados com ausência geológica?</span></div>`}catch(e){host.textContent='Não foi possível concluir a missão nesta sessão. '+(e.message||e)}}
function itaDetectiveSaved(){try{return JSON.parse(localStorage.getItem('ita_arandu_detetive_lacunas_v38')||'[]')}catch(_){return[]}}
function itaDetectiveSave(){const stat=document.getElementById('detetiveSalvarStatus'),last=window.ITA_DETETIVE_LAST;if(!last?.hex_id){if(stat)stat.textContent='Analise primeiro um hexágono.';return}const lacunas=[...document.querySelectorAll('input[name="detetiveGap"]:checked')].map(x=>x.value),pergunta=String(document.getElementById('detetivePergunta')?.value||'').trim(),estrategia=String(document.getElementById('detetiveEstrategia')?.value||'').trim();if(!pergunta){if(stat)stat.textContent='Formule uma pergunta investigável antes de guardar.';return}const rec={...last,lacunas_identificadas:lacunas,pergunta_investigacao:pergunta,estrategia_proposta:estrategia,principio:'SEM_DADO != AUSENCIA_GEOLOGICA',criado_em:new Date().toISOString(),versao:'V38'};const arr=itaDetectiveSaved();arr.push(rec);try{localStorage.setItem('ita_arandu_detetive_lacunas_v38',JSON.stringify(arr));if(stat)stat.textContent=`Ficha guardada · ${arr.length} registro(s) no dispositivo. Os dados permanecem locais até a exportação.`}catch(e){if(stat)stat.textContent='Não foi possível guardar localmente. '+(e.message||e)}}
function itaDetectiveExport(){const arr=itaDetectiveSaved(),stat=document.getElementById('detetiveSalvarStatus');if(!arr.length){if(stat)stat.textContent='Ainda não existem fichas guardadas para exportar.';return}const payload={produto:'ITA ARANDU MS · Detetive das lacunas',versao:'V38',regra:'IMC e IPG descrevem dimensões distintas do conhecimento. Ausência de dado não equivale a ausência geológica.',exportado_em:new Date().toISOString(),fichas:arr};const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='ITA_ARANDU_DETETIVE_DAS_LACUNAS_V38.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);if(stat)stat.textContent=`${arr.length} ficha(s) exportada(s) em JSON.`}
