/* V38.4.28 · troca explícita entre snapshot local e fonte online */
if(!window.__ITA_PROVENIENCIA_MODE_LISTENER__){
 window.__ITA_PROVENIENCIA_MODE_LISTENER__=true;
 document.addEventListener('ita:layer-source-mode',async e=>{
  const id=e.detail?.id;
  const cfg=CATALOG.layers.find(x=>x.id===id);
  if(!cfg)return;
  state.layers.delete(id);
  if(state.active.has(id)){
   try{await ensure(cfg)}
   catch(err){
    state.active.delete(id);
    const cb=document.querySelector(`input[data-layer="${id}"]`);
    if(cb)cb.checked=false;
    alert(err?.message||String(err));
   }
  }
  try{updateLayerCard(id)}catch(_){}
  try{render()}catch(_){}
 });
}

/* V38.4.29 mobile map toolbar integrated */
(function itaInstallMobileMapToolbarState(){
  if(window.__ITA_MOBILE_MAP_TOOLBAR_38429__)return;
  window.__ITA_MOBILE_MAP_TOOLBAR_38429__=true;
  const sync=()=>{
    const base=document.getElementById('basemapPanel');
    const legend=document.getElementById('mapLegend');
    document.getElementById('mobileBaseBtn')?.classList.toggle('is-open',!!base?.classList.contains('mobile-open'));
    document.getElementById('mobileLegendBtn')?.classList.toggle('is-open',!!legend?.classList.contains('mobile-open'));
  };
  ['mobileBaseBtn','mobileLegendBtn','closeBasePanel','closeLegendPanel'].forEach(id=>{
    document.getElementById(id)?.addEventListener('click',()=>requestAnimationFrame(sync));
  });
  document.querySelectorAll('input[name="basemap"]').forEach(el=>{
    el.addEventListener('change',()=>requestAnimationFrame(sync));
  });
  const observe=id=>{
    const el=document.getElementById(id);
    if(el)new MutationObserver(sync).observe(el,{attributes:true,attributeFilter:['class']});
  };
  observe('basemapPanel');
  observe('mapLegend');
  sync();
})();
